1","DEVA","A","A-PID"],["DEV-A","User requirements specification (BOCRA website)","Phase 1","DEVA","A","A-REQ"],["DEV-A","Website design (UI and UX) (BOCRA website)","Phase 2","DEVA","A","A-DES"],["DEV-A","Frontend build (BOCRA website)","Phase 2","DEVA","A","A-FE"],["DEV-A","Backend and CMS build (BOCRA website)","Phase 2","DEVA","A","A-BE"],["DEV-A","UAT support and test evidence (BOCRA website)","Phase 3","DEVA","A","A-UAT"],["DEV-A","Handover pack (BOCRA website)","Phase 3","DEVA","A","A-HO"],["DEV-A","Production deployment (BOCRA website)","Phase 3","DEVA","A","A-DEP"],["DEV-B","Project Initiation Document (PID) (UASF website)","Phase 1","DEVB","B","B-PID"],["DEV-B","User requirements specification (UASF website)","Phase 1","DEVB","B","B-REQ"],["DEV-B","Website design (UI and UX) (UASF website)","Phase 2","DEVB","B","B-DES"],["DEV-B","Frontend build (UASF website)","Phase 2","DEVB","B","B-FE"],["DEV-B","Backend and CMS build (UASF website)","Phase 2","DEVB","B","B-BE"],["DEV-B","UAT support and test evidence (UASF website)","Phase 3","DEVB","B","B-UAT"],["DEV-B","Handover pack (UASF website)","Phase 3","DEVB","B","B-HO"],["DEV-B","Production deployment (UASF website)","Phase 3","DEVB","B","B-DEP"],["D2","D2 Review of PIDs, plans and user requirements","Phase 1","BDIH","S","D2"],["D4","D4 Milestone readiness recommendations","Phase 2","BDIH","S","D4"],["D5","D5 UAT coordination and defect report","Phase 3","BDIH","S","D5"],["D6","D6 Handover verification report","Phase 3","BDIH","S","D6"],["D7","D7 Closure report and lessons learned","Phase 3","BDIH","S","D7"],["D3","D3 Monthly progress reports","Phase 2","BDIH","S","MR-NOV"]]'; bid uuid;
begin
  if exists (select 1 from activities) then raise exception 'The plan already has activities; nothing was loaded.'; end if;
  insert into activities (display_order, workstream_id, phase, name, type, review_stage, deliverable_ref, lead_resource_id, support_resource_id, duration, fixed_start, visible_to_developers, submittable, doc_category, indent, key)
  select (x->>'o')::int, (select id from workstreams where code = x->>'w'), x->>'p', x->>'n', (x->>'t')::activity_type, (x->>'r')::review_stage, x->>'ref',
         (select id from resources where name = x->>'l'), (select id from resources where name = x->>'s'), (x->>'d')::int, (x->>'f')::date, (x->>'v')::boolean, (x->>'sub')::boolean, x->>'dc', (x->>'in')::int, x->>'k'
  from jsonb_array_elements(a) x;
  update activities t set bdih_review_activity_id = (select id from activities where key = x->>'br'), bocra_review_activity_id = (select id from activities where key = x->>'or'), for_activity_id = (select id from activities where key = x->>'fo')
  from jsonb_array_elements(a) x where t.key = x->>'k' and (x->>'br' is not null or x->>'or' is not null or x->>'fo' is not null);
  insert into activity_links (predecessor_id, successor_id, link_type, lag)
  select (select id from activities where key = x->>0), (select id from activities where key = x->>1), 'FS', (x->>2)::int from jsonb_array_elements(l) x;
  insert into deliverables (ref, name, phase, owner_organisation_id, workstream_id, activity_id)
  select x->>0, x->>1, x->>2, (select id from organisations where short_name = x->>3), (select id from workstreams where code = x->>4), (select id from activities where key = x->>5) from jsonb_array_elements(dl) x;
  insert into baselines (name) values ('Original baseline (approved with D1)') returning id into bid;
  insert into baseline_items (baseline_id, activity_id, start_date, finish_date) select bid, id, start_date, finish_date from activities where deleted_at is null;
  update settings set current_baseline_id = bid;
end $plan$;
